    #[test]
    fn split_java_string_matches_the_jvm_shapes_mods_use() {
        assert_eq!(
            split_java_string("a\r\nb\nc", "\\R", 0).unwrap(),
            ["a", "b", "c"]
        );
        assert_eq!(
            split_java_string("a   b\tc", "\\s+", 0).unwrap(),
            ["a", "b", "c"]
        );
        assert_eq!(
            split_java_string("a b  c", "\\s", 0).unwrap(),
            ["a", "b", "", "c"]
        );
        assert_eq!(
            split_java_string("a.b.c", "\\.", 0).unwrap(),
            ["a", "b", "c"]
        );
        // A pattern that never matched answers one part, even for "".
        assert_eq!(split_java_string("abc", ",", 0).unwrap(), ["abc"]);
        assert_eq!(split_java_string("", ",", 0).unwrap(), [""]);
        // limit > 0 applies the pattern at most limit - 1 times.
        assert_eq!(split_java_string("a,b,c", ",", 1).unwrap(), ["a,b,c"]);
        assert_eq!(split_java_string("a,b,c", ",", 2).unwrap(), ["a", "b,c"]);
        // limit 0 drops trailing empties; a negative limit keeps them.
        assert_eq!(split_java_string("a,b,,", ",", 0).unwrap(), ["a", "b"]);
        assert_eq!(
            split_java_string("a,b,,", ",", -1).unwrap(),
            ["a", "b", "", ""]
        );
        // Every part empty and trailing: Java answers an empty array.
        assert_eq!(
            split_java_string(",", ",", 0).unwrap(),
            Vec::<String>::new()
        );
    }

    #[test]
    fn split_java_string_answers_general_patterns_like_the_jvm() {
        // `"a,b".split(pattern)` on OpenJDK 27.
        let cases: &[(&str, &[&str])] = &[
            ("", &["a", ",", "b"]),
            ("[,;]", &["a", "b"]),
            ("a|b", &["", ","]),
            (",+", &["a", "b"]),
            ("(x)", &["a,b"]),
        ];
        for (pattern, expected) in cases {
            assert_eq!(
                split_java_string("a,b", pattern, 0).unwrap(),
                *expected,
                "{pattern:?}"
            );
        }
    }

    #[test]
    fn split_java_string_names_patterns_outside_the_subset() {
        for pattern in ["\\p{IsAlphabetic}", "(?x) a", "a{"] {
            let error = split_java_string("a,b", pattern, 0).unwrap_err();
            assert!(error.contains(pattern), "{pattern:?}: {error}");
        }
    }

    #[test]
    fn describe_value_names_the_received_representation() {
        assert_eq!(describe_value(&Value::Ref(None)), "null");
        assert_eq!(describe_value(&Value::Int(3)), "int 3");
        assert_eq!(
            describe_value(&Value::Ref(Some("array/demo/run/0".into()))),
            "marker \"array/demo/run/0\""
        );
        let long = "x".repeat(200);
        let described = describe_value(&Value::Ref(Some(long)));
        assert!(described.chars().count() < 120, "{described}");
        assert!(described.ends_with("..."), "{described}");
    }
    #[test]
    fn metadata_accepts_object_version() {
        assert_eq!(
            parse_metadata(r#"{"id":"demo","version":{"semver":"1.2.3"},"entrypoints":{"client":"demo.Client::boot"}}"#).unwrap(),
            (
                Some("demo".into()),
                Some("1.2.3".into()),
                BTreeMap::from([(
                    "client".into(),
                    vec![Entrypoint {
                            class: "demo.Client".into(),
                        method: Some("boot".into()),
                        adapter: None,
                    }]
                )]),
                Vec::<String>::new(),
            )
        );
    }

    #[test]
    fn invokedynamic_captures_stay_bounded_across_concat_chains() {
        // One captured marker is transcribed up to the bound, never whole.
        let captured = bounded_captured_markers(&[Value::Ref(Some("x".repeat(1 << 20)))]);
        assert_eq!(
            captured.chars().count(),
            4097,
            "4096 transcribed + ellipsis"
        );
        assert!(captured.ends_with('\u{2026}'), "{captured}");

        // A concat site captures the previous concat's marker text, so a real
        // chain nests. Each link adds one bounded prefix instead of doubling:
        // transcription used to grow without limit here.
        let mut value = Value::Ref(Some("x".repeat(64)));
        for _ in 0..64 {
            let captured = bounded_captured_markers(std::slice::from_ref(&value));
            value = Value::Ref(Some(format!("@indy:demo/C#m:0:?:{captured}")));
        }
        let Value::Ref(Some(marker)) = &value else {
            panic!("expected a marker");
        };
        assert!(
            marker.chars().count() < 64 * (4096 + 128),
            "{}",
            marker.chars().count()
        );
    }

    #[test]
    fn metadata_accepts_a_raw_control_character_inside_a_string() {
        // Gson's lenient parser, which Fabric reads the metadata with, accepts
        // the multiline `description` real jars ship. A strict parser rejects
        // the whole document, losing the id, the entrypoints and the configs.
        let text = "{\n\t\"schemaVersion\": 1,\n\t\"id\": \"weaponmaster\",\n\t\"version\": \"4.4.3\",\n\t\"description\": \"first line\nsecond line\twith a tab\u{0008} and a form\u{000c} feed\",\n\t\"entrypoints\": {\"main\": [\"demo.Main\"]},\n\t\"mixins\": [\"demo.mixins.json\"]\n}";
        let (id, version, entrypoints, _) = parse_metadata(text).unwrap();
        assert_eq!(id.as_deref(), Some("weaponmaster"));
        assert_eq!(version.as_deref(), Some("4.4.3"));
        assert_eq!(entrypoints["main"][0].class, "demo.Main");
        assert_eq!(
            fabric_mixin_config_paths(text),
            Some(vec!["demo.mixins.json".to_owned()])
        );
        // A valid document is returned unchanged.
        assert!(matches!(
            lenient_json_text(r#"{"id":"demo"}"#),
            Cow::Borrowed(_)
        ));
        let rewritten =
            lenient_json_text("{\"description\":\"tab\tback\u{0008}form\u{000c}feed\nline\"}");
        assert_eq!(
            rewritten,
            r#"{"description":"tab\tback\bform\ffeed\nline"}"#
        );
        let error = parse_metadata(r#"{"id":"demo\q"}"#).unwrap_err();
        assert!(matches!(error, NativeError::Metadata(_)), "{error}");
        let error = parse_metadata(r#"{"id" "demo"}"#).unwrap_err();
        assert!(matches!(error, NativeError::Metadata(_)), "{error}");
    }

