    /// The metadata-first read keeps the loader's decisions but does not parse
    /// class files or retain ordinary resource payloads; a jar chosen to run is
    /// read again with `from_path`, which does.
    #[test]
    fn metadata_read_skips_class_parsing_and_resource_payloads() {
        let path = std::env::temp_dir().join(format!(
            "horizon-native-metadata-only-{}.jar",
            std::process::id()
        ));
        let file = File::create(&path).unwrap();
        let mut zip = zip::ZipWriter::new(file);
        let options = zip::write::SimpleFileOptions::default();
        zip.start_file("fabric.mod.json", options).unwrap();
        zip.write_all(br#"{"id":"demo","version":"1.0","entrypoints":{"main":["demo.Main"]}}"#)
            .unwrap();
        zip.start_file("demo/Main.class", options).unwrap();
        zip.write_all(&weavable_class_bytes("demo/Main")).unwrap();
        zip.start_file("demo/Broken.class", options).unwrap();
        zip.write_all(b"not a class file").unwrap();
        zip.start_file("data/blob.bin", options).unwrap();
        zip.write_all(b"payload").unwrap();
        zip.finish().unwrap();

        let metadata = NativeJar::from_path_metadata(&path).unwrap();
        assert_eq!(metadata.fabric_id.as_deref(), Some("demo"));
        assert!(
            !metadata.discover_entrypoints("main").is_empty(),
            "loader metadata still names the entrypoint"
        );
        assert!(
            metadata
                .resource_names()
                .any(|name| name == "data/blob.bin")
        );
        assert!(metadata.classes.is_empty(), "no class is parsed");
        assert!(metadata.neoforge_entrypoints.is_empty());
        assert!(
            !metadata.resource_bytes.contains_key("data/blob.bin"),
            "a jar that will not run keeps no resource payload"
        );
        assert!(
            NativeJar::from_path(&path).is_err(),
            "the full read still parses every class"
        );
        std::fs::remove_file(path).unwrap();
    }

    #[test]
    fn mixin_configs_discover_root_configs_without_fabric_metadata() {
        let path = std::env::temp_dir().join(format!(
            "horizon-native-mixin-config-discovery-{}.jar",
            std::process::id()
        ));
        let file = File::create(&path).unwrap();
        let mut zip = zip::ZipWriter::new(file);
        let options = zip::write::SimpleFileOptions::default();
        zip.start_file("auto.mixins.json", options).unwrap();
        zip.write_all(br#"{"mixins":["demo.AutoMixin"]}"#).unwrap();
        zip.start_file("nested/nested.mixins.json", options)
            .unwrap();
        zip.write_all(br#"{"mixins":["demo.NestedMixin"]}"#)
            .unwrap();
        zip.finish().unwrap();

        let jar = NativeJar::from_path(&path).unwrap();
        let configs = jar.mixin_configs();
        assert_eq!(
            configs
                .iter()
                .map(|config| config.path.as_str())
                .collect::<Vec<_>>(),
            ["auto.mixins.json"],
            "only root-level configs are discovered without metadata"
        );
        assert_eq!(configs[0].mixins, ["demo.AutoMixin"]);
        // Mixin's defaults: required unless declared, no priority.
        assert!(configs[0].required);
        assert_eq!(configs[0].priority, None);
        assert!(jar.mixin_config_errors().is_empty());
        let warnings = jar.mixin_config_warnings();
        assert_eq!(warnings.len(), 1, "unexpected warnings: {warnings:#?}");
        assert!(
            warnings[0].starts_with("auto.mixins.json:")
                && warnings[0].contains("root-level fallback"),
            "unexpected warning: {}",
            warnings[0]
        );
        std::fs::remove_file(path).unwrap();
    }

    #[test]
    fn mixin_configs_follow_declared_loader_order() {
        let mut jar = NativeJar::default();
        jar.resource_bytes.insert(
            "fabric.mod.json".into(),
            br#"{"id":"ordered","mixins":["zeta.mixins.json","alpha.mixins.json"]}"#.to_vec(),
        );
        jar.resource_bytes.insert(
            "zeta.mixins.json".into(),
            br#"{"mixins":["demo.ZetaMixin"]}"#.to_vec(),
        );
        jar.resource_bytes.insert(
            "alpha.mixins.json".into(),
            br#"{"mixins":["demo.AlphaMixin"]}"#.to_vec(),
        );
        assert_eq!(
            jar.mixin_configs()
                .iter()
                .map(|config| config.path.as_str())
                .collect::<Vec<_>>(),
            ["zeta.mixins.json", "alpha.mixins.json"],
            "one priority tie is broken by fabric.mod.json order, not path order"
        );
        assert!(jar.mixin_config_warnings().is_empty());
    }

