    #[test]
    fn legacy_forge_manifest_declares_the_jars_mixin_configs() {
        let mut jar = NativeJar::from_classes([target_class()]);
        jar.resource_bytes.insert(
            "META-INF/MANIFEST.MF".into(),
            concat!(
                "Manifest-Version: 1.0\r\n",
                "MixinConfigs: legacy.mixins.json,\r\n",
                " extra.mixins.json\r\n",
            )
            .as_bytes()
            .to_vec(),
        );
        for path in ["legacy.mixins.json", "extra.mixins.json"] {
            jar.resource_bytes.insert(
                path.into(),
                format!(
                    r#"{{"mixins":["demo.{}"]}}"#,
                    path.trim_end_matches(".mixins.json")
                )
                .into_bytes(),
            );
        }
        let paths = jar
            .mixin_configs()
            .into_iter()
            .map(|config| config.path)
            .collect::<Vec<_>>();
        assert_eq!(paths, ["legacy.mixins.json", "extra.mixins.json"]);
        assert!(
            jar.mixin_config_errors()
                .iter()
                .all(|(path, _)| !path.contains("MANIFEST")),
            "a readable manifest is a declaration, not an error"
        );
    }

    #[test]
    fn mixin_config_bounds_reject_oversized_files_and_entry_lists() {
        let oversized = vec![b' '; MAX_MIXIN_CONFIG_BYTES + 1];
        let error = parse_mixin_config("big.mixins.json", &oversized).unwrap_err();
        assert!(error.contains("byte bound"), "unexpected reason: {error}");

        let mixins = (0..=MAX_MIXIN_CONFIG_CLASSES)
            .map(|index| format!("\"Mixin{index}\""))
            .collect::<Vec<_>>()
            .join(",");
        let text = format!("{{\"package\":\"demo.mixin\",\"mixins\":[{mixins}]}}");
        let error = parse_mixin_config("many.mixins.json", text.as_bytes()).unwrap_err();
        assert!(
            error.contains("more than 4096 class entries"),
            "unexpected reason: {error}"
        );
    }

    #[test]
    fn mixin_config_rejects_invalid_class_and_package_names() {
        let text = br#"{"package":"demo.mixin","mixins":["Bad/Name"]}"#;
        let error = parse_mixin_config("bad.mixins.json", text).unwrap_err();
        assert!(
            error.contains("invalid mixin class name Bad/Name"),
            "unexpected reason: {error}"
        );

        let text = br#"{"package":"demo..mixin","mixins":["Fine"]}"#;
        let error = parse_mixin_config("package.mixins.json", text).unwrap_err();
        assert!(
            error.contains("invalid mixin package demo..mixin"),
            "unexpected reason: {error}"
        );
    }

    #[test]
    fn mixin_config_keeps_declaration_order_and_deduplicates() {
        let text = br#"{"package":"demo.mixin","mixins":["Beta","Alpha","Beta"],"client":["demo.mixin.Alpha"]}"#;
        let config = parse_mixin_config("demo.mixins.json", text).unwrap();
        assert_eq!(
            config.mixins,
            ["demo.mixin.Beta", "demo.mixin.Alpha"],
            "declaration order survives, a repeated class appears once"
        );
        assert_eq!(
            config.client,
            ["demo.mixin.Alpha"],
            "an already-qualified entry is not prefixed twice"
        );
    }

    #[test]
    fn jar_seeds_bundled_resources_into_the_bounded_host() {
        let path = std::env::temp_dir().join(format!(
            "horizon-native-resource-seeding-{}.jar",
            std::process::id()
        ));
        let file = File::create(&path).unwrap();
        let mut zip = zip::ZipWriter::new(file);
        let options = zip::write::SimpleFileOptions::default();
        zip.start_file("fabric.mod.json", options).unwrap();
        zip.write_all(
            br#"{"id":"resource-fixture","version":"1.0","entrypoints":{"main":"demo.Main"}}"#,
        )
        .unwrap();
        zip.start_file("assets/resource-fixture/lang/en_us.json", options)
            .unwrap();
        zip.write_all(br#"{"item.resource-fixture.wand":"Wand"}"#)
            .unwrap();
        zip.start_file("data/resource-fixture/recipes/wand.json", options)
            .unwrap();
        zip.write_all(br#"{"type":"minecraft:crafting_shaped"}"#)
            .unwrap();
        zip.finish().unwrap();

        let jar = NativeJar::from_path(&path).unwrap();
        let names = jar.resource_names().collect::<Vec<_>>();
        assert_eq!(
            names,
            vec![
                "assets/resource-fixture/lang/en_us.json",
                "data/resource-fixture/recipes/wand.json",
                "fabric.mod.json",
            ]
        );
        let mut host = jar.seed_host(StdHost::new());
        assert_eq!(
            host.resource("assets/resource-fixture/lang/en_us.json"),
            Some("jar-resource/assets/resource-fixture/lang/en_us.json")
        );
        assert_eq!(
            host.resource("/data/resource-fixture/recipes/wand.json"),
            Some("jar-resource/data/resource-fixture/recipes/wand.json")
        );
        let stream = MethodRef {
            owner: "java/lang/ClassLoader".into(),
            name: "getSystemResourceAsStream".into(),
            descriptor: "(Ljava/lang/String;)Ljava/io/InputStream;".into(),
        };
        let stream_value = host
            .invoke(
                &stream,
                &[Value::Ref(Some(
                    "assets/resource-fixture/lang/en_us.json".into(),
                ))],
            )
            .unwrap();
        let read = MethodRef {
            owner: "java/io/InputStream".into(),
            name: "read".into(),
            descriptor: "()I".into(),
        };
        assert_eq!(
            host.invoke_instance(&read, &stream_value, &[]).unwrap(),
            Value::Int(i32::from(b'{'))
        );
        std::fs::remove_file(path).unwrap();
    }

