    /// Runs `f` on a thread with a `stack`-byte stack: 2 MiB is what the
    /// game's server, render and worker threads run with, so a bound proven
    /// there holds where jars run.
    fn on_a_thread_stack<T: Send + 'static>(
        stack: usize,
        f: impl FnOnce() -> T + Send + 'static,
    ) -> T {
        std::thread::Builder::new()
            .name("recursion-bound".into())
            .stack_size(stack)
            .spawn(f)
            .expect("spawn the bounded thread")
            .join()
            .expect("the depth bound keeps the recursion on its own stack")
    }

    /// `static int f(int n) { return f(n); }`
    fn recurse_class() -> ClassFile {
        ClassFile {
            name: "demo/Recurse".into(),
            super_name: "java/lang/Object".into(),
            pool: vec![
                Cp::Empty,
                Cp::MethodRef { class: 2, nt: 3 },
                Cp::Class(4),
                Cp::NameType {
                    name: 5,
                    descriptor: 6,
                },
                Cp::Utf8("demo/Recurse".into()),
                Cp::Utf8("f".into()),
                Cp::Utf8("(I)I".into()),
            ],
            bootstrap_methods: Vec::new(),
            fields: Vec::new(),
            methods: vec![Method {
                name: "f".into(),
                descriptor: "(I)I".into(),
                access: 9,
                code: Some(vec![0x1a, 0xb8, 0x00, 0x01, 0xac]),
                max_locals: 1,
                max_stack: 1,

                annotations: Vec::new(),
            }],

            annotations: Vec::new(),
            raw: Vec::new(),
        }
    }

    /// `static int down(int n) { if (n == 0) return 0; return down(n - 1); }`
    fn countdown_class() -> ClassFile {
        ClassFile {
            name: "demo/Countdown".into(),
            super_name: "java/lang/Object".into(),
            pool: vec![
                Cp::Empty,
                Cp::MethodRef { class: 2, nt: 3 },
                Cp::Class(4),
                Cp::NameType {
                    name: 5,
                    descriptor: 6,
                },
                Cp::Utf8("demo/Countdown".into()),
                Cp::Utf8("down".into()),
                Cp::Utf8("(I)I".into()),
            ],
            bootstrap_methods: Vec::new(),
            fields: Vec::new(),
            methods: vec![Method {
                name: "down".into(),
                descriptor: "(I)I".into(),
                access: 9,
                code: Some(vec![
                    0x1a, 0x99, 0x00, 0x05, 0x03, 0xac, 0x1a, 0x04, 0x64, 0xb8, 0x00, 0x01, 0xac,
                ]),
                max_locals: 1,
                max_stack: 1,

                annotations: Vec::new(),
            }],

            annotations: Vec::new(),
            raw: Vec::new(),
        }
    }

    /// Recurse without bound on a `stack`-byte thread; answers the depth the
    /// bound refused at.
    fn unbounded_recursion_depth(stack: usize) -> usize {
        on_a_thread_stack(stack, move || {
            let jar = NativeJar::from_classes([recurse_class()]);
            let error = jar
                .invoke_method_with_args(
                    "demo.Recurse",
                    "f",
                    "(I)I",
                    None,
                    &[Value::Int(1)],
                    &mut NullHost,
                )
                .expect_err("an unbounded recursion must fail");
            let text = error.to_string();
            match error {
                NativeError::CallDepthExceeded {
                    class,
                    method,
                    limit,
                } => {
                    assert_eq!(class, "demo/Recurse");
                    assert_eq!(method, "f");
                    assert!(
                        text.contains(&format!(
                            "after {limit} nested jar frames at demo/Recurse#f"
                        )),
                        "{text}"
                    );
                    limit
                }
                other => panic!("expected the depth bound, got {other:?}"),
            }
        })
    }

    /// A jar that recurses without bound is one failed jar, not a process
    /// abort: the interpreter's frames are Rust frames, and a stack overflow
    /// cannot be caught by the batch's `catch_unwind`.
    #[test]
    fn unbounded_recursion_fails_with_the_depth_bound() {
        let depth = unbounded_recursion_depth(2 << 20);
        assert!(depth >= 1, "a 2 MiB thread runs at least one frame");
    }

    /// The bound is the thread's stack, not a fixed count: four times the
    /// stack nests more frames, and the count cap stops a recursion that
    /// would otherwise fill a very large stack.
    #[test]
    fn the_depth_bound_follows_the_threads_stack() {
        let game_thread = unbounded_recursion_depth(2 << 20);
        let main_thread = unbounded_recursion_depth(8 << 20);
        assert!(
            main_thread > game_thread,
            "8 MiB nests {main_thread}, 2 MiB {game_thread}"
        );
        assert_eq!(
            unbounded_recursion_depth(1 << 30),
            frame_bound::MAX_JAR_CALL_DEPTH
        );
    }

    /// The bound leaves a legitimate recursive method alone: a chain deeper
    /// than the old fixed bound of 12 (unoptimised) answers normally on a
    /// thread whose stack holds it, as the JVM's would.
    #[test]
    fn recursion_below_the_bound_still_runs() {
        let result = on_a_thread_stack(64 << 20, move || {
            NativeJar::from_classes([countdown_class()])
                .invoke_method_with_args(
                    "demo.Countdown",
                    "down",
                    "(I)I",
                    None,
                    &[Value::Int(200)],
                    &mut NullHost,
                )
                .unwrap()
        });
        assert_eq!(result, Value::Int(0));
    }

    /// A jar that loops without calling anything still stops at its budget:
    /// the check also runs inside a frame, not only when a frame is entered.
    #[test]
    fn a_jar_that_never_returns_stops_at_its_execution_budget() {
        // `static void spin() { while (true) {} }`
        let class = ClassFile {
            name: "demo/Spin".into(),
            super_name: "java/lang/Object".into(),
            pool: vec![Cp::Empty],
            bootstrap_methods: Vec::new(),
            fields: Vec::new(),
            methods: vec![Method {
                name: "spin".into(),
                descriptor: "()V".into(),
                access: 9,
                code: Some(vec![0xa7, 0x00, 0x00]),
                max_locals: 0,
                max_stack: 0,

                annotations: Vec::new(),
            }],

            annotations: Vec::new(),
            raw: Vec::new(),
        };
        let jar = NativeJar::from_classes([class]);
        let limit = std::time::Duration::from_millis(5);
        let budget = ExecutionBudget::within(limit);
        let started = std::time::Instant::now();
        let error = jar
            .execute_with_budget("demo.Spin", Some("spin"), "main", &mut NullHost, &budget)
            .expect_err("a loop past its budget must fail");
        assert!(
            started.elapsed() >= limit,
            "the budget was honoured, not guessed: {:?}",
            started.elapsed()
        );
        match error {
            NativeError::ExecutionBudgetExceeded {
                class,
                method,
                budget,
            } => {
                assert_eq!(class, "demo/Spin");
                assert_eq!(method, "spin");
                assert_eq!(budget, limit);
            }
            other => panic!("expected the execution budget, got {other:?}"),
        }
    }

    #[test]
    fn neoforge_marker_is_discoverable_without_fml() {
        let class = ClassFile {
            name: "demo/NeoMod".into(),
            super_name: "java/lang/Object".into(),
            pool: vec![Cp::Empty, Cp::Utf8("Lnet/neoforged/fml/common/Mod;".into())],
            bootstrap_methods: Vec::new(),
            fields: Vec::new(),
            methods: vec![],

            annotations: Vec::new(),
            raw: Vec::new(),
        };
        let jar = NativeJar::from_classes([class]);
        assert_eq!(
            jar.discover_entrypoint("neoforge").unwrap().class,
            "demo.NeoMod"
        );
        assert!(jar.discover_entrypoint("main").is_none());
        assert!(jar.discover_entrypoint("client").is_none());
    }

    #[test]
    fn legacy_forge_metadata_and_mod_marker_are_discoverable() {
        let class = ClassFile {
            name: "demo/ForgeMod".into(),
            super_name: "java/lang/Object".into(),
            pool: vec![
                Cp::Empty,
                Cp::Utf8("Lnet/minecraftforge/fml/common/Mod;".into()),
            ],
            bootstrap_methods: Vec::new(),
            fields: Vec::new(),
            methods: vec![],

            annotations: Vec::new(),
            raw: Vec::new(),
        };
        let jar = NativeJar::from_classes([class]);
        assert_eq!(
            jar.discover_entrypoint("neoforge").unwrap().class,
            "demo.ForgeMod"
        );

        let text = r#"
[[mods]]
modId = "legacy"
version = "1.0"
[[dependencies.legacy]]
modId = "library"
mandatory = true
"#;
        let (id, version, required, client_side_only) = parse_neoforge_metadata(text).unwrap();
        assert_eq!(id.as_deref(), Some("legacy"));
        assert_eq!(version.as_deref(), Some("1.0"));
        assert_eq!(required, ["library"]);
        assert!(!client_side_only);
    }

