    #[test]
    fn standard_host_rejects_service_loader_classpath_scanning() {
        let mut host = StdHost::new();
        for (name, descriptor) in [
            ("load", "(Ljava/lang/Class;)Ljava/util/ServiceLoader;"),
            (
                "loadInstalled",
                "(Ljava/lang/Class;)Ljava/util/ServiceLoader;",
            ),
        ] {
            let method = MethodRef {
                owner: "java/util/ServiceLoader".into(),
                name: name.into(),
                descriptor: descriptor.into(),
            };
            // A JDK service could have providers on a real class path the
            // native runtime never sees, so it stays refused.
            let error = host.invoke(&method, &[Value::Ref(Some("java/sql/Driver".into()))]);
            assert!(matches!(
                error,
                Err(NativeError::Metadata(message))
                    if message.contains("ServiceLoader")
                        && message.contains("host classpath scanning is disabled")
            ));
        }
    }

    #[test]
    fn standard_host_answers_an_empty_loader_for_an_unprovided_mod_service() {
        // A mod's own API interface with no `META-INF/services` row in any
        // seeded or linked jar: the JVM's loader iterates nothing.
        let mut host = StdHost::new();
        let load = MethodRef {
            owner: "java/util/ServiceLoader".into(),
            name: "load".into(),
            descriptor: "(Ljava/lang/Class;)Ljava/util/ServiceLoader;".into(),
        };
        let loader = host
            .invoke(&load, &[Value::Ref(Some("demo/api/Integration".into()))])
            .unwrap();
        let iterator = host
            .invoke_instance(
                &MethodRef {
                    owner: "java/util/ServiceLoader".into(),
                    name: "iterator".into(),
                    descriptor: "()Ljava/util/Iterator;".into(),
                },
                &loader,
                &[],
            )
            .unwrap();
        let has_next = MethodRef {
            owner: "java/util/Iterator".into(),
            name: "hasNext".into(),
            descriptor: "()Z".into(),
        };
        assert_eq!(
            host.invoke_instance(&has_next, &iterator, &[]).unwrap(),
            Value::Int(0)
        );
        let first = MethodRef {
            owner: "java/util/ServiceLoader".into(),
            name: "findFirst".into(),
            descriptor: "()Ljava/util/Optional;".into(),
        };
        assert_eq!(
            host.invoke_instance(&first, &loader, &[]).unwrap(),
            empty_optional()
        );
    }

    #[test]
    fn standard_host_loads_only_explicit_service_providers() {
        let mut host = StdHost::new()
            .with_service_provider("demo/Provider", "demo.FirstProvider")
            .with_service_provider("demo/Provider", "demo.SecondProvider");
        assert_eq!(
            host.service_providers("demo/Provider"),
            Some(
                [
                    "demo.FirstProvider".to_owned(),
                    "demo.SecondProvider".to_owned()
                ]
                .as_slice()
            )
        );
        let load = MethodRef {
            owner: "java/util/ServiceLoader".into(),
            name: "load".into(),
            descriptor: "(Ljava/lang/Class;)Ljava/util/ServiceLoader;".into(),
        };
        let loader = host
            .invoke(&load, &[Value::Ref(Some("demo.Provider".into()))])
            .unwrap();
        assert_eq!(
            loader,
            Value::Ref(Some("service-loader/demo/Provider".into()))
        );
        let iterator = host
            .invoke_instance(
                &MethodRef {
                    owner: "java/util/ServiceLoader".into(),
                    name: "iterator".into(),
                    descriptor: "()Ljava/util/Iterator;".into(),
                },
                &loader,
                &[],
            )
            .unwrap();
        let next = MethodRef {
            owner: "java/util/Iterator".into(),
            name: "next".into(),
            descriptor: "()Ljava/lang/Object;".into(),
        };
        assert_eq!(
            host.invoke_instance(&next, &iterator, &[]).unwrap(),
            Value::Ref(Some("demo.FirstProvider".into()))
        );
        assert_eq!(
            host.invoke_instance(&next, &iterator, &[]).unwrap(),
            Value::Ref(Some("demo.SecondProvider".into()))
        );
    }

    #[test]
    fn standard_host_maps_common_queries_and_records_calls() {
        let mut host = StdHost::new().with_property("demo.mode", "native");
        let property = MethodRef {
            owner: "java/lang/System".into(),
            name: "getProperty".into(),
            descriptor: "(Ljava/lang/String;)Ljava/lang/String;".into(),
        };
        assert_eq!(
            host.invoke(&property, &[Value::Ref(Some("demo.mode".into()))])
                .unwrap(),
            Value::Ref(Some("native".into()))
        );
        let property_with_default = MethodRef {
            owner: "java/lang/System".into(),
            name: "getProperty".into(),
            descriptor: "(Ljava/lang/String;Ljava/lang/String;)Ljava/lang/String;".into(),
        };
        assert_eq!(
            host.invoke(
                &property_with_default,
                &[
                    Value::Ref(Some("demo.mode".into())),
                    Value::Ref(Some("fallback".into())),
                ],
            )
            .unwrap(),
            Value::Ref(Some("native".into()))
        );
        assert_eq!(
            host.invoke(
                &property_with_default,
                &[
                    Value::Ref(Some("missing.mode".into())),
                    Value::Ref(Some("fallback".into())),
                ],
            )
            .unwrap(),
            Value::Ref(Some("fallback".into()))
        );
        let parse = MethodRef {
            owner: "java/lang/Integer".into(),
            name: "parseInt".into(),
            descriptor: "(Ljava/lang/String;)I".into(),
        };
        assert_eq!(
            host.invoke(&parse, &[Value::Ref(Some("7".into()))])
                .unwrap(),
            Value::Int(7)
        );
        let parse_radix = MethodRef {
            owner: "java/lang/Integer".into(),
            name: "parseInt".into(),
            descriptor: "(Ljava/lang/String;I)I".into(),
        };
        assert_eq!(
            host.invoke(
                &parse_radix,
                &[Value::Ref(Some("ff".into())), Value::Int(16)],
            )
            .unwrap(),
            Value::Int(255)
        );
        let value_of_radix = MethodRef {
            owner: "java/lang/Integer".into(),
            name: "valueOf".into(),
            descriptor: "(Ljava/lang/String;I)Ljava/lang/Integer;".into(),
        };
        assert_eq!(
            host.invoke(
                &value_of_radix,
                &[Value::Ref(Some("101".into())), Value::Int(2)],
            )
            .unwrap(),
            Value::Boxed(Boxed::Integer(5))
        );
        let compare = MethodRef {
            owner: "java/lang/Integer".into(),
            name: "compare".into(),
            descriptor: "(II)I".into(),
        };
        assert_eq!(
            host.invoke(&compare, &[Value::Int(-2), Value::Int(7)])
                .unwrap(),
            Value::Int(-1)
        );
        let hex = MethodRef {
            owner: "java/lang/Integer".into(),
            name: "toHexString".into(),
            descriptor: "(I)Ljava/lang/String;".into(),
        };
        assert_eq!(
            host.invoke(&hex, &[Value::Int(255)]).unwrap(),
            Value::Ref(Some("ff".into()))
        );
        let long_compare = MethodRef {
            owner: "java/lang/Long".into(),
            name: "compare".into(),
            descriptor: "(JJ)I".into(),
        };
        assert_eq!(
            host.invoke(&long_compare, &[Value::Int(4), Value::Int(9)])
                .unwrap(),
            Value::Int(-1)
        );
        let long_hex = MethodRef {
            owner: "java/lang/Long".into(),
            name: "toHexString".into(),
            descriptor: "(J)Ljava/lang/String;".into(),
        };
        assert_eq!(
            host.invoke(&long_hex, &[Value::Int(255)]).unwrap(),
            Value::Ref(Some("ff".into()))
        );
        assert_eq!(
            host.invoke(&long_hex, &[Value::Long(-1)]).unwrap(),
            Value::Ref(Some("ffffffffffffffff".into()))
        );
        assert_eq!(
            host.calls(),
            &[
                property,
                property_with_default.clone(),
                property_with_default,
                parse,
                parse_radix,
                value_of_radix,
                compare,
                hex,
                long_compare,
                long_hex.clone(),
                long_hex,
            ]
        );
    }

    #[test]
    fn standard_host_classloader_resources_are_explicit_and_host_local() {
        let mut host = StdHost::new().with_resource("assets/demo.txt", "resource/demo");
        assert_eq!(host.resource("assets/demo.txt"), Some("resource/demo"));
        assert_eq!(host.resource("/assets/demo.txt"), Some("resource/demo"));
        assert_eq!(host.resource("missing.txt"), None);

        let loader = Value::Ref(Some("classloader/bootstrap".into()));
        let url = MethodRef {
            owner: "java/lang/ClassLoader".into(),
            name: "getResource".into(),
            descriptor: "(Ljava/lang/String;)Ljava/net/URL;".into(),
        };
        assert_eq!(
            host.invoke_instance(&url, &loader, &[Value::Ref(Some("assets/demo.txt".into()))])
                .unwrap(),
            Value::Ref(Some("resource/demo".into()))
        );
        let stream = MethodRef {
            name: "getResourceAsStream".into(),
            descriptor: "(Ljava/lang/String;)Ljava/io/InputStream;".into(),
            ..url.clone()
        };
        assert_eq!(
            host.invoke_instance(&stream, &loader, &[Value::Ref(Some("missing.txt".into()))])
                .unwrap(),
            Value::Ref(None)
        );
        host = host.with_resource_bytes("assets/bytes.bin", vec![97, 98, 99]);
        let byte_stream = host
            .invoke_instance(
                &stream,
                &loader,
                &[Value::Ref(Some("assets/bytes.bin".into()))],
            )
            .unwrap();
        let read = MethodRef {
            owner: "java/io/InputStream".into(),
            name: "read".into(),
            descriptor: "()I".into(),
        };
        let available = MethodRef {
            owner: "java/io/InputStream".into(),
            name: "available".into(),
            descriptor: "()I".into(),
        };
        let skip = MethodRef {
            owner: "java/io/InputStream".into(),
            name: "skip".into(),
            descriptor: "(J)J".into(),
        };
        assert_eq!(
            host.invoke_instance(&available, &byte_stream, &[]).unwrap(),
            Value::Int(3)
        );
        assert_eq!(
            host.invoke_instance(&read, &byte_stream, &[]).unwrap(),
            Value::Int(97)
        );
        assert_eq!(
            host.invoke_instance(&skip, &byte_stream, &[Value::Int(1)])
                .unwrap(),
            Value::Int(1)
        );
        assert_eq!(
            host.invoke_instance(&read, &byte_stream, &[]).unwrap(),
            Value::Int(99)
        );
        assert_eq!(
            host.invoke_instance(&read, &byte_stream, &[]).unwrap(),
            Value::Int(-1)
        );
        let mark_supported = MethodRef {
            owner: "java/io/InputStream".into(),
            name: "markSupported".into(),
            descriptor: "()Z".into(),
        };
        let mark = MethodRef {
            owner: "java/io/InputStream".into(),
            name: "mark".into(),
            descriptor: "(I)V".into(),
        };
        let reset = MethodRef {
            owner: "java/io/InputStream".into(),
            name: "reset".into(),
            descriptor: "()V".into(),
        };
        assert_eq!(
            host.invoke_instance(&mark_supported, &byte_stream, &[])
                .unwrap(),
            Value::Int(1)
        );
        let marked_stream = host
            .invoke_instance(
                &stream,
                &loader,
                &[Value::Ref(Some("/assets/bytes.bin".into()))],
            )
            .unwrap();
        host.invoke_instance(&mark, &marked_stream, &[Value::Int(0)])
            .unwrap();
        assert_eq!(
            host.invoke_instance(&read, &marked_stream, &[]).unwrap(),
            Value::Int(97)
        );
        host.invoke_instance(&reset, &marked_stream, &[]).unwrap();
        assert_eq!(
            host.invoke_instance(&read, &marked_stream, &[]).unwrap(),
            Value::Int(97)
        );
        let skip_n = MethodRef {
            owner: "java/io/InputStream".into(),
            name: "skipNBytes".into(),
            descriptor: "(J)V".into(),
        };
        assert!(
            host.invoke_instance(&skip_n, &marked_stream, &[Value::Int(3)])
                .is_err()
        );

        let resources = MethodRef {
            owner: "java/lang/ClassLoader".into(),
            name: "getResources".into(),
            descriptor: "(Ljava/lang/String;)Ljava/util/Enumeration;".into(),
        };
        let enumeration = host
            .invoke_instance(
                &resources,
                &loader,
                &[Value::Ref(Some("assets/demo.txt".into()))],
            )
            .unwrap();
        let has_more = MethodRef {
            owner: "java/util/Enumeration".into(),
            name: "hasMoreElements".into(),
            descriptor: "()Z".into(),
        };
        let next = MethodRef {
            owner: "java/util/Enumeration".into(),
            name: "nextElement".into(),
            descriptor: "()Ljava/lang/Object;".into(),
        };
        assert_eq!(
            host.invoke_instance(&has_more, &enumeration, &[]).unwrap(),
            Value::Int(1)
        );
        assert_eq!(
            host.invoke_instance(&next, &enumeration, &[]).unwrap(),
            Value::Ref(Some("resource/demo".into()))
        );
        assert_eq!(
            host.invoke_instance(&has_more, &enumeration, &[]).unwrap(),
            Value::Int(0)
        );

        let missing = host
            .invoke(
                &MethodRef {
                    owner: "java/lang/ClassLoader".into(),
                    name: "getSystemResources".into(),
                    descriptor: "(Ljava/lang/String;)Ljava/util/Enumeration;".into(),
                },
                &[Value::Ref(Some("missing.txt".into()))],
            )
            .unwrap();
        assert_eq!(
            host.invoke_instance(&has_more, &missing, &[]).unwrap(),
            Value::Int(0)
        );
    }

    #[test]
    fn standard_host_classloader_loads_only_explicit_classes() {
        let mut host = StdHost::new().with_class("demo.Provider");
        assert_eq!(host.class_marker("demo/Provider"), Some("demo/Provider"));
        let loader = Value::Ref(Some("classloader/bootstrap".into()));
        let load = MethodRef {
            owner: "java/lang/ClassLoader".into(),
            name: "loadClass".into(),
            descriptor: "(Ljava/lang/String;)Ljava/lang/Class;".into(),
        };
        assert_eq!(
            host.invoke_instance(&load, &loader, &[Value::Ref(Some("demo.Provider".into()))],)
                .unwrap(),
            Value::Ref(Some("demo/Provider".into()))
        );
        let missing = host
            .invoke_instance(
                &load,
                &loader,
                &[Value::Ref(Some("missing.Provider".into()))],
            )
            .unwrap_err()
            .to_string();
        assert!(missing.contains("not explicitly seeded"), "{missing}");
    }

    #[test]
    fn standard_host_maps_integer_floor_math() {
        let mut host = StdHost::new();
        let floor_div = MethodRef {
            owner: "java/lang/Math".into(),
            name: "floorDiv".into(),
            descriptor: "(II)I".into(),
        };
        assert_eq!(
            host.invoke(&floor_div, &[Value::Int(-7), Value::Int(3)])
                .unwrap(),
            Value::Int(-3)
        );
        let floor_mod = MethodRef {
            owner: "java/lang/Math".into(),
            name: "floorMod".into(),
            descriptor: "(II)I".into(),
        };
        assert_eq!(
            host.invoke(&floor_mod, &[Value::Int(-7), Value::Int(3)])
                .unwrap(),
            Value::Int(2)
        );
        assert_eq!(
            host.invoke(&floor_mod, &[Value::Int(7), Value::Int(-3)])
                .unwrap(),
            Value::Int(-2)
        );
        assert_eq!(
            host.invoke(&floor_mod, &[Value::Int(i32::MIN), Value::Int(-1)])
                .unwrap(),
            Value::Int(0)
        );
    }

    #[test]
    fn standard_host_maps_bounded_long_parsing() {
        let mut host = StdHost::new();
        let parse = MethodRef {
            owner: "java/lang/Long".into(),
            name: "parseLong".into(),
            descriptor: "(Ljava/lang/String;)J".into(),
        };
        let value = host
            .invoke(&parse, &[Value::Ref(Some("9223372036854775807".into()))])
            .unwrap();
        assert_eq!(value, Value::Long(9_223_372_036_854_775_807));
        assert_eq!(
            host.invoke(
                &MethodRef {
                    owner: "java/lang/Long".into(),
                    name: "toString".into(),
                    descriptor: "(J)Ljava/lang/String;".into(),
                },
                std::slice::from_ref(&value),
            )
            .unwrap(),
            Value::Ref(Some("9223372036854775807".into()))
        );
        assert_eq!(
            host.invoke(
                &MethodRef {
                    owner: "java/lang/Long".into(),
                    name: "parseLong".into(),
                    descriptor: "(Ljava/lang/String;I)J".into(),
                },
                &[Value::Ref(Some("ff".into())), Value::Int(16)],
            )
            .unwrap(),
            Value::Long(255)
        );
        assert!(
            host.invoke(&parse, &[Value::Ref(Some("oops".into()))])
                .is_err()
        );
    }

    #[test]
    fn standard_host_prints_parses_and_boxes_exact_longs() {
        let mut host = StdHost::new();
        let method = |owner: &str, name: &str, descriptor: &str| MethodRef {
            owner: owner.into(),
            name: name.into(),
            descriptor: descriptor.into(),
        };
        let max = 9_223_372_036_854_775_807i64;

        // `Long.valueOf` is the boxing site javac emits for `Long b = v`.
        let boxed = host
            .invoke(
                &method("java/lang/Long", "valueOf", "(J)Ljava/lang/Long;"),
                &[Value::Long(max)],
            )
            .unwrap();
        assert_eq!(boxed, Value::Long(max));

        assert_eq!(
            host.invoke_instance(&method("java/lang/Long", "longValue", "()J"), &boxed, &[],)
                .unwrap(),
            Value::Long(max)
        );
        assert_eq!(
            host.invoke_instance(
                &method("java/lang/Long", "toString", "()Ljava/lang/String;"),
                &boxed,
                &[],
            )
            .unwrap(),
            Value::Ref(Some("9223372036854775807".into()))
        );
        assert_eq!(
            host.invoke_instance(
                &method("java/lang/Long", "intValue", "()I"),
                &Value::Long(4_294_967_297),
                &[],
            )
            .unwrap(),
            Value::Int(1)
        );
        assert_eq!(
            host.invoke_instance(
                &method("java/lang/Long", "compareTo", "(Ljava/lang/Long;)I"),
                &Value::Long(-4_294_967_297),
                &[Value::Long(0)],
            )
            .unwrap(),
            Value::Int(-1)
        );
        assert_eq!(
            host.invoke_instance(
                &method("java/lang/Long", "equals", "(Ljava/lang/Object;)Z"),
                &Value::Long(4_294_967_297),
                &[Value::Long(4_294_967_297)],
            )
            .unwrap(),
            Value::Int(1)
        );
        assert_eq!(
            host.invoke_instance(
                &method("java/lang/Long", "equals", "(Ljava/lang/Object;)Z"),
                &Value::Long(4_294_967_297),
                &[Value::Long(4_294_967_298)],
            )
            .unwrap(),
            Value::Int(0)
        );

        // `Long.hashCode(J)` is `(int) (v ^ (v >>> 32))`, so 2^32 + 1 is 0.
        assert_eq!(
            host.invoke(
                &method("java/lang/Long", "hashCode", "(J)I"),
                &[Value::Long(4_294_967_297)],
            )
            .unwrap(),
            Value::Int(0)
        );
        assert_eq!(
            host.invoke(
                &method("java/lang/Long", "sum", "(JJ)J"),
                &[Value::Long(max), Value::Long(1)],
            )
            .unwrap(),
            Value::Long(i64::MIN)
        );
        assert_eq!(
            host.invoke(
                &method("java/lang/Long", "max", "(JJ)J"),
                &[Value::Long(-2), Value::Long(3)],
            )
            .unwrap(),
            Value::Long(3)
        );
        assert_eq!(
            host.invoke(
                &method("java/lang/Long", "min", "(JJ)J"),
                &[Value::Long(-2), Value::Long(3)],
            )
            .unwrap(),
            Value::Long(-2)
        );

        // `String.valueOf`, `StringBuilder.append` and `String.format("%d")`
        // must all print the exact long.
        assert_eq!(
            host.invoke(
                &method("java/lang/String", "valueOf", "(J)Ljava/lang/String;"),
                &[Value::Long(max)],
            )
            .unwrap(),
            Value::Ref(Some("9223372036854775807".into()))
        );
        assert_eq!(
            host.invoke_instance(
                &MethodRef {
                    owner: "java/lang/StringBuilder".into(),
                    name: "append".into(),
                    descriptor: "(J)Ljava/lang/StringBuilder;".into(),
                },
                &Value::Ref(Some("string-builder/fixture".into())),
                &[Value::Long(4_294_967_297)],
            )
            .unwrap(),
            Value::Ref(Some("string-builder/fixture4294967297".into()))
        );

        assert_eq!(Value::default_for("J"), Value::Long(0));
        assert_eq!(Value::default_for("()J"), Value::Long(0));
    }

    #[test]
    fn long_value_markers_round_trip_for_callback_captures() {
        let value = Value::Long(-4_294_967_297);
        assert_eq!(value_marker(&value), "l-4294967297");
        assert_eq!(parse_value_marker(&value_marker(&value)).unwrap(), value);
    }

    #[test]
    fn float_opcodes_keep_exact_float_and_double_values() {
        let method = |name: &str, descriptor: &str, locals: u16, code: Vec<u8>| Method {
            name: name.into(),
            descriptor: descriptor.into(),
            access: 9,
            code: Some(code),
            max_locals: locals,
            max_stack: 4,
            annotations: Vec::new(),
        };
        let class = ClassFile {
            name: "demo/FloatMath".into(),
            super_name: "java/lang/Object".into(),
            // 1: float 1.25, 2: double 0.1, 3: double 0.2, 4: double NaN,
            // 5: long 2^32+1
            pool: vec![
                Cp::Empty,
                Cp::Float(1.25),
                Cp::Double(0.1),
                Cp::Double(0.2),
                Cp::Double(f64::NAN),
                Cp::Long(4_294_967_297),
            ],
            bootstrap_methods: Vec::new(),
            fields: Vec::new(),
            methods: vec![
                // fconst_0/1/2 and the `fadd` result rounding to `f32`.
                method("fconstZero", "()F", 0, vec![0x0b, 0xae]),
                method("fconstOne", "()F", 0, vec![0x0c, 0xae]),
                method("fconstTwo", "()F", 0, vec![0x0d, 0xae]),
                method("fconstAdd", "()F", 0, vec![0x0c, 0x0d, 0x62, 0xae]),
                // dconst_0/1 with `dsub`.
                method("dconstSub", "()D", 0, vec![0x0e, 0x0f, 0x67, 0xaf]),
                // `ldc` reads the float pool value, `ldc2_w` the double.
                method("floatConstant", "()F", 0, vec![0x12, 0x01, 0xae]),
                method("doubleConstant", "()D", 0, vec![0x14, 0x00, 0x02, 0xaf]),
                method(
                    "doubleAdd",
                    "()D",
                    0,
                    // ldc2_w 0.1; ldc2_w 0.2; dadd
                    vec![0x14, 0x00, 0x02, 0x14, 0x00, 0x03, 0x63, 0xaf],
                ),
                method(
                    "doubleDiv",
                    "()D",
                    0,
                    vec![0x14, 0x00, 0x02, 0x14, 0x00, 0x03, 0x6f, 0xaf],
                ),
                method(
                    "doubleRem",
                    "()D",
                    0,
                    vec![0x14, 0x00, 0x03, 0x14, 0x00, 0x02, 0x72, 0xaf],
                ),
                method("doubleNeg", "()D", 0, vec![0x14, 0x00, 0x02, 0x77, 0xaf]),
                method("floatNeg", "()F", 0, vec![0x12, 0x01, 0x76, 0xae]),
                // dcmpl/dcmpg/fcmpl/fcmpg, including the NaN answers.
                method(
                    "doubleCompareLess",
                    "()I",
                    0,
                    vec![0x14, 0x00, 0x02, 0x14, 0x00, 0x03, 0x97, 0xac],
                ),
                method(
                    "doubleCompareGreater",
                    "()I",
                    0,
                    vec![0x14, 0x00, 0x03, 0x14, 0x00, 0x02, 0x98, 0xac],
                ),
                method(
                    "nanCompareLess",
                    "()I",
                    0,
                    vec![0x14, 0x00, 0x02, 0x14, 0x00, 0x04, 0x97, 0xac],
                ),
                method(
                    "nanCompareGreater",
                    "()I",
                    0,
                    vec![0x14, 0x00, 0x02, 0x14, 0x00, 0x04, 0x98, 0xac],
                ),
                method(
                    "floatCompareLess",
                    "()I",
                    0,
                    vec![0x0c, 0x12, 0x01, 0x95, 0xac],
                ),
                method(
                    "floatCompareGreater",
                    "()I",
                    0,
                    vec![0x12, 0x01, 0x0c, 0x96, 0xac],
                ),
                // Every numeric conversion the JVM defines for the widths.
                method("intToFloat", "()F", 0, vec![0x10, 0x03, 0x86, 0xae]),
                method("intToDouble", "()D", 0, vec![0x10, 0x03, 0x87, 0xaf]),
                method("longToFloat", "()F", 0, vec![0x14, 0x00, 0x05, 0x89, 0xae]),
                method("longToDouble", "()D", 0, vec![0x14, 0x00, 0x05, 0x8a, 0xaf]),
                method("floatToInt", "()I", 0, vec![0x12, 0x01, 0x8b, 0xac]),
                method("floatToLong", "()J", 0, vec![0x12, 0x01, 0x8c, 0xad]),
                method("floatToDouble", "()D", 0, vec![0x12, 0x01, 0x8d, 0xaf]),
                method("doubleToInt", "()I", 0, vec![0x14, 0x00, 0x02, 0x8e, 0xac]),
                method("doubleToLong", "()J", 0, vec![0x14, 0x00, 0x02, 0x8f, 0xad]),
                method(
                    "doubleToFloat",
                    "()F",
                    0,
                    vec![0x14, 0x00, 0x02, 0x90, 0xae],
                ),
                // A `float`/`double` local round trip (each wide local is two
                // slots, and `dload_2`/`dstore_2` address the second).
                method("doubleLocal", "(D)D", 4, vec![0x26, 0x49, 0x28, 0xaf]),
                method("floatLocal", "(F)F", 2, vec![0x22, 0x44, 0x23, 0xae]),
                // `new double[2]`/`new float[1]` with `daload`/`dastore`.
                method(
                    "doubleArray",
                    "(D)D",
                    3,
                    vec![0x05, 0xbc, 0x07, 0x59, 0x03, 0x26, 0x52, 0x03, 0x31, 0xaf],
                ),
                method(
                    "floatArray",
                    "(F)F",
                    2,
                    vec![0x04, 0xbc, 0x06, 0x59, 0x03, 0x22, 0x51, 0x03, 0x30, 0xae],
                ),
                // A read-before-write element is the element type's zero.
                method(
                    "doubleArrayDefault",
                    "()D",
                    1,
                    vec![0x04, 0xbc, 0x07, 0x03, 0x31, 0xaf],
                ),
                // `pop2`/`dup2` treat the wide value as one category-2 slot.
                method("discardDouble", "()D", 0, vec![0x0f, 0x58, 0x0e, 0xaf]),
                method("duplicateDouble", "()D", 0, vec![0x0f, 0x5c, 0x63, 0xaf]),
            ],
            annotations: Vec::new(),
            raw: Vec::new(),
        };
        let jar = NativeJar::from_classes([class]);
        let mut host = NullHost;
        let mut call = |name: &str, descriptor: &str, args: &[Value]| {
            jar.invoke_method_with_args("demo.FloatMath", name, descriptor, None, args, &mut host)
                .unwrap()
        };

        assert_eq!(call("fconstZero", "()F", &[]), Value::Float(0.0));
        assert_eq!(call("fconstOne", "()F", &[]), Value::Float(1.0));
        assert_eq!(call("fconstTwo", "()F", &[]), Value::Float(2.0));
        assert_eq!(call("fconstAdd", "()F", &[]), Value::Float(3.0));
        assert_eq!(call("dconstSub", "()D", &[]), Value::Float(-1.0));
        assert_eq!(call("floatConstant", "()F", &[]), Value::Float(1.25));
        assert_eq!(call("doubleConstant", "()D", &[]), Value::Float(0.1));
        assert_eq!(call("doubleAdd", "()D", &[]), Value::Float(0.1 + 0.2));
        assert_eq!(call("doubleDiv", "()D", &[]), Value::Float(0.5));
        assert_eq!(call("doubleRem", "()D", &[]), Value::Float(0.2 % 0.1));
        assert_eq!(call("doubleNeg", "()D", &[]), Value::Float(-0.1));
        assert_eq!(
            call("floatNeg", "()F", &[]),
            Value::Float(f64::from(-1.25f32))
        );
        assert_eq!(call("doubleCompareLess", "()I", &[]), Value::Int(-1));
        assert_eq!(call("doubleCompareGreater", "()I", &[]), Value::Int(1));
        assert_eq!(call("nanCompareLess", "()I", &[]), Value::Int(-1));
        assert_eq!(call("nanCompareGreater", "()I", &[]), Value::Int(1));
        assert_eq!(call("floatCompareLess", "()I", &[]), Value::Int(-1));
        assert_eq!(call("floatCompareGreater", "()I", &[]), Value::Int(1));

        assert_eq!(call("intToFloat", "()F", &[]), Value::Float(3.0));
        assert_eq!(call("intToDouble", "()D", &[]), Value::Float(3.0));
        assert_eq!(
            call("longToFloat", "()F", &[]),
            Value::Float(f64::from(4_294_967_297i64 as f32))
        );
        assert_eq!(
            call("longToDouble", "()D", &[]),
            Value::Float(4_294_967_297_f64)
        );
        assert_eq!(call("floatToInt", "()I", &[]), Value::Int(1));
        assert_eq!(call("floatToLong", "()J", &[]), Value::Long(1));
        assert_eq!(
            call("floatToDouble", "()D", &[]),
            Value::Float(f64::from(1.25f32))
        );
        assert_eq!(call("doubleToInt", "()I", &[]), Value::Int(0));
        assert_eq!(call("doubleToLong", "()J", &[]), Value::Long(0));
        assert_eq!(
            call("doubleToFloat", "()F", &[]),
            Value::Float(f64::from(0.1f32))
        );

        assert_eq!(
            call("doubleLocal", "(D)D", &[Value::Float(0.1 + 0.2)]),
            Value::Float(0.1 + 0.2)
        );
        assert_eq!(
            call("floatLocal", "(F)F", &[Value::Float(1.25)]),
            Value::Float(1.25)
        );
        assert_eq!(
            call("doubleArray", "(D)D", &[Value::Float(0.1 + 0.2)]),
            Value::Float(0.1 + 0.2)
        );
        assert_eq!(
            call("floatArray", "(F)F", &[Value::Float(1.25)]),
            Value::Float(1.25)
        );
        assert_eq!(call("doubleArrayDefault", "()D", &[]), Value::Float(0.0));
        assert_eq!(call("discardDouble", "()D", &[]), Value::Float(0.0));
        assert_eq!(call("duplicateDouble", "()D", &[]), Value::Float(2.0));

        assert_eq!(Value::default_for("F"), Value::Float(0.0));
        assert_eq!(Value::default_for("()F"), Value::Float(0.0));
        assert_eq!(Value::default_for("D"), Value::Float(0.0));
        assert_eq!(Value::default_for("()D"), Value::Float(0.0));
    }

    #[test]
    fn standard_host_boxes_parses_and_prints_exact_floats() {
        let mut host = StdHost::new();
        let method = |owner: &str, name: &str, descriptor: &str| MethodRef {
            owner: owner.into(),
            name: name.into(),
            descriptor: descriptor.into(),
        };

        // `Double.valueOf(D)` is the boxing site javac emits for `Double d = v`.
        let boxed = host
            .invoke(
                &method("java/lang/Double", "valueOf", "(D)Ljava/lang/Double;"),
                &[Value::Float(0.1 + 0.2)],
            )
            .unwrap();
        assert_eq!(boxed, Value::Float(0.1 + 0.2));
        assert_eq!(
            host.invoke_instance(
                &method("java/lang/Double", "doubleValue", "()D"),
                &boxed,
                &[],
            )
            .unwrap(),
            Value::Float(0.1 + 0.2)
        );
        assert_eq!(
            host.invoke_instance(
                &method("java/lang/Double", "intValue", "()I"),
                &Value::Float(-3.75),
                &[],
            )
            .unwrap(),
            Value::Int(-3)
        );
        assert_eq!(
            host.invoke_instance(
                &method("java/lang/Double", "longValue", "()J"),
                &Value::Float(4_294_967_297.9),
                &[],
            )
            .unwrap(),
            Value::Long(4_294_967_297)
        );
        assert_eq!(
            host.invoke_instance(
                &method("java/lang/Double", "toString", "()Ljava/lang/String;"),
                &Value::Float(0.1 + 0.2),
                &[],
            )
            .unwrap(),
            Value::Ref(Some("0.30000000000000004".into()))
        );
        assert_eq!(
            host.invoke_instance(
                &method("java/lang/Double", "compareTo", "(Ljava/lang/Double;)I"),
                &Value::Float(f64::NAN),
                &[Value::Float(1.0)],
            )
            .unwrap(),
            Value::Int(1)
        );
        assert_eq!(
            host.invoke_instance(
                &method("java/lang/Double", "equals", "(Ljava/lang/Object;)Z"),
                &Value::Float(f64::NAN),
                &[Value::Float(f64::NAN)],
            )
            .unwrap(),
            Value::Int(1)
        );
        assert_eq!(
            host.invoke_instance(
                &method("java/lang/Double", "equals", "(Ljava/lang/Object;)Z"),
                &Value::Float(0.0),
                &[Value::Float(-0.0)],
            )
            .unwrap(),
            Value::Int(0)
        );

        // `Float.valueOf(F)` rounds the argument to `f32`, and the boxed
        // `Float.toString` prints the `f32` digits rather than the widened ones.
        let boxed_float = host
            .invoke(
                &method("java/lang/Float", "valueOf", "(F)Ljava/lang/Float;"),
                &[Value::Float(0.1)],
            )
            .unwrap();
        assert_eq!(boxed_float, Value::Boxed(Boxed::float(0.1)));
        assert_eq!(
            host.invoke_instance(
                &method("java/lang/Float", "toString", "()Ljava/lang/String;"),
                &boxed_float,
                &[],
            )
            .unwrap(),
            Value::Ref(Some("0.1".into()))
        );
        assert_eq!(
            host.invoke(
                &method("java/lang/Float", "parseFloat", "(Ljava/lang/String;)F"),
                &[Value::Ref(Some("1.25".into()))],
            )
            .unwrap(),
            Value::Float(1.25)
        );
        assert_eq!(
            host.invoke(
                &method("java/lang/Double", "parseDouble", "(Ljava/lang/String;)D"),
                &[Value::Ref(Some("-Infinity".into()))],
            )
            .unwrap(),
            Value::Float(f64::NEG_INFINITY)
        );
        assert_eq!(
            host.invoke(
                &method("java/lang/Double", "isFinite", "(D)Z"),
                &[Value::Float(f64::INFINITY)],
            )
            .unwrap(),
            Value::Int(0)
        );
        assert_eq!(
            host.invoke(
                &method("java/lang/Float", "compare", "(FF)I"),
                &[Value::Float(f64::from(f32::NAN)), Value::Float(1.0)],
            )
            .unwrap(),
            Value::Int(1)
        );
        assert_eq!(
            host.invoke(
                &method("java/lang/Double", "max", "(DD)D"),
                &[Value::Float(2.5), Value::Float(-1.5)],
            )
            .unwrap(),
            Value::Float(2.5)
        );
        assert_eq!(
            host.invoke(
                &method("java/lang/Double", "min", "(DD)D"),
                &[Value::Float(2.5), Value::Float(-1.5)],
            )
            .unwrap(),
            Value::Float(-1.5)
        );

        // The static bounds keep their exact bits.
        assert_eq!(
            host.get_static(&method("java/lang/Double", "MAX_VALUE", "D"))
                .unwrap(),
            Value::Float(f64::MAX)
        );
        assert_eq!(
            host.get_static(&method("java/lang/Float", "MAX_VALUE", "F"))
                .unwrap(),
            Value::Float(f64::from(f32::MAX))
        );
        // `MIN_VALUE` is the smallest subnormal, `MIN_NORMAL` the smallest
        // normal, as in Java.
        assert_eq!(
            host.get_static(&method("java/lang/Double", "MIN_VALUE", "D"))
                .unwrap(),
            Value::Float(f64::from_bits(1))
        );
        assert_eq!(
            host.get_static(&method("java/lang/Double", "MIN_NORMAL", "D"))
                .unwrap(),
            Value::Float(f64::MIN_POSITIVE)
        );
        assert_eq!(
            host.get_static(&method("java/lang/Float", "MIN_VALUE", "F"))
                .unwrap(),
            Value::Float(f64::from(f32::from_bits(1)))
        );

        // `String.valueOf`, `StringBuilder.append` and `String.format("%f")`.
        assert_eq!(
            host.invoke(
                &method("java/lang/String", "valueOf", "(D)Ljava/lang/String;"),
                &[Value::Float(0.1 + 0.2)],
            )
            .unwrap(),
            Value::Ref(Some("0.30000000000000004".into()))
        );
        assert_eq!(
            host.invoke(
                &method("java/lang/String", "valueOf", "(F)Ljava/lang/String;"),
                &[Value::Float(0.1)],
            )
            .unwrap(),
            Value::Ref(Some("0.1".into()))
        );
        assert_eq!(
            host.invoke_instance(
                &MethodRef {
                    owner: "java/lang/StringBuilder".into(),
                    name: "append".into(),
                    descriptor: "(D)Ljava/lang/StringBuilder;".into(),
                },
                &Value::Ref(Some("string-builder/fixture".into())),
                &[Value::Float(0.1 + 0.2)],
            )
            .unwrap(),
            Value::Ref(Some("string-builder/fixture0.30000000000000004".into()))
        );
    }

    #[test]
    fn float_value_markers_round_trip_for_callback_captures() {
        let value = Value::Float(-0.30000000000000004);
        assert_eq!(value_marker(&value), "f-0.30000000000000004");
        assert_eq!(parse_value_marker(&value_marker(&value)).unwrap(), value);

        // Non-finite captures keep the Java spelling and parse back exactly.
        for special in [f64::NAN, f64::INFINITY, f64::NEG_INFINITY, -0.0] {
            let value = Value::Float(special);
            let marker = value_marker(&value);
            let parsed = parse_value_marker(&marker).unwrap();
            match (parsed, special) {
                (Value::Float(parsed), special) => {
                    assert_eq!(parsed.to_bits(), special.to_bits(), "marker {marker}")
                }
                other => panic!("expected a float capture, got {other:?}"),
            }
        }
    }

    #[test]
    fn java_float_text_matches_double_to_string() {
        assert_eq!(format_java_float(3.5), "3.5");
        assert_eq!(format_java_float(1.0), "1.0");
        assert_eq!(format_java_float(100.0), "100.0");
        assert_eq!(format_java_float(0.001), "0.001");
        assert_eq!(format_java_float(1e-4), "1.0E-4");
        assert_eq!(format_java_float(1e7), "1.0E7");
        assert_eq!(format_java_float(1234567.0), "1234567.0");
        assert_eq!(format_java_float(-0.0), "-0.0");
        assert_eq!(format_java_float(f64::MAX), "1.7976931348623157E308");
        // `f32` shortest digits, not the widened `f64` spelling.
        assert_eq!(format_java_float32(0.1), "0.1");
        assert_eq!(format_java_float32(f64::from(f32::MAX)), "3.4028235E38");
    }

    #[test]
    fn standard_host_maps_character_queries_and_boxing() {
        let mut host = StdHost::new();
        let letter = MethodRef {
            owner: "java/lang/Character".into(),
            name: "isLetter".into(),
            descriptor: "(C)Z".into(),
        };
        assert_eq!(
            host.invoke(&letter, &[Value::Int('Æ' as i32)]).unwrap(),
            Value::Int(1)
        );
        let digit = MethodRef {
            name: "isDigit".into(),
            descriptor: "(I)Z".into(),
            ..letter.clone()
        };
        assert_eq!(
            host.invoke(&digit, &[Value::Int('७' as i32)]).unwrap(),
            Value::Int(1)
        );
        let lower = MethodRef {
            name: "toLowerCase".into(),
            descriptor: "(C)C".into(),
            ..letter.clone()
        };
        assert_eq!(
            host.invoke(&lower, &[Value::Int('Q' as i32)]).unwrap(),
            Value::Int('q' as i32)
        );
        let value_of = MethodRef {
            name: "valueOf".into(),
            descriptor: "(C)Ljava/lang/Character;".into(),
            ..letter.clone()
        };
        let boxed = host.invoke(&value_of, &[Value::Int('Z' as i32)]).unwrap();
        assert_eq!(boxed, Value::Boxed(Boxed::Character(90)));
        assert_eq!(
            host.invoke_instance(
                &MethodRef {
                    name: "charValue".into(),
                    descriptor: "()C".into(),
                    ..letter.clone()
                },
                &boxed,
                &[]
            )
            .unwrap(),
            Value::Int('Z' as i32)
        );
        assert_eq!(
            host.invoke_instance(
                &MethodRef {
                    name: "toString".into(),
                    descriptor: "()Ljava/lang/String;".into(),
                    ..letter
                },
                &boxed,
                &[]
            )
            .unwrap(),
            Value::Ref(Some("Z".into()))
        );
    }

