        assert_eq!(
            host.invoke_instance(
                &put_if_absent,
                &map,
                &[
                    Value::Ref(Some("other".into())),
                    Value::Ref(Some("added".into()))
                ],
            )
            .unwrap(),
            Value::Ref(None)
        );
        let replace = MethodRef {
            owner: "java/util/Map".into(),
            name: "replace".into(),
            descriptor: "(Ljava/lang/Object;Ljava/lang/Object;)Ljava/lang/Object;".into(),
        };
