    #[test]
    fn jar_owned_new_allocations_have_distinct_instance_identity() {
        let classes = BTreeMap::new();
        let mut host = NullHost;
        let mut runtime = Runtime {
            classes: &classes,
            linked: Arc::default(),
            host: &mut host,
            calls: 0,
            fields: BTreeMap::new(),
            static_fields: BTreeMap::new(),
            initialized_classes: std::collections::BTreeSet::new(),
            arrays: BTreeMap::new(),
            next_array: 0,
            next_object: 0,
            streams: BTreeMap::new(),
            next_stream: 0,
            enum_constants: BTreeMap::new(),
            string_builders: BTreeMap::new(),
            string_readers: BTreeMap::new(),
            io_writers: BTreeMap::new(),
            io_paths: BTreeMap::new(),
            io_files: BTreeMap::new(),
            io_dirs: BTreeSet::new(),
            watch: watch_service::WatchState::default(),
            annotations: BTreeMap::new(),
            next_annotation: 0,
            callback_infos: &mut CallbackInfos::new(),
            invoke_hooks: None,
            anchor_hooks: None,
            modify_hooks: None,
            pending_skipped_new: Vec::new(),
            depth: 0,
            budget: &ExecutionBudget::UNBOUNDED,
        };
        let first = runtime.new_object("demo/Fields");
        let second = runtime.new_object("demo/Fields");
        assert_ne!(first, second);
        let field = MethodRef {
            owner: "demo/Fields".into(),
            name: "value".into(),
            descriptor: "I".into(),
        };
        runtime
            .fields
            .insert(instance_field_key(&first, &field).unwrap(), Value::Int(7));
        assert_eq!(
            runtime
                .fields
                .get(&instance_field_key(&first, &field).unwrap()),
            Some(&Value::Int(7))
        );
        assert!(
            !runtime
                .fields
                .contains_key(&instance_field_key(&second, &field).unwrap())
        );
    }

