    #[test]
    fn reflective_array_surface_uses_runtime_owned_arrays() {
        let classes = BTreeMap::new();
        let mut host = NullHost;
        let mut runtime = Runtime {
            classes: &classes,
            linked: Arc::default(),
            host: &mut host,
            calls: 0,
            fields: BTreeMap::new(),
            static_fields: BTreeMap::new(),
            initialized_classes: std::collections::BTreeSet::new(),
            arrays: BTreeMap::new(),
            next_array: 0,
            next_object: 0,
            streams: BTreeMap::new(),
            next_stream: 0,
            enum_constants: BTreeMap::new(),
            string_builders: BTreeMap::new(),
            string_readers: BTreeMap::new(),
            io_writers: BTreeMap::new(),
            io_paths: BTreeMap::new(),
            io_files: BTreeMap::new(),
            io_dirs: BTreeSet::new(),
            watch: watch_service::WatchState::default(),
            annotations: BTreeMap::new(),
            next_annotation: 0,
            callback_infos: &mut CallbackInfos::new(),
            invoke_hooks: None,
            anchor_hooks: None,
            modify_hooks: None,
            pending_skipped_new: Vec::new(),
            depth: 0,
            budget: &ExecutionBudget::UNBOUNDED,
        };
        let new_instance = MethodRef {
            owner: "java/lang/reflect/Array".into(),
            name: "newInstance".into(),
            descriptor: "(Ljava/lang/Class;I)Ljava/lang/Object;".into(),
        };
        let array = runtime
            .invoke_reflect_array(
                &new_instance,
                &[Value::Ref(Some("java/lang/String".into())), Value::Int(2)],
                "demo/Reflective",
                "probe",
            )
            .unwrap()
            .unwrap();
        let set = MethodRef {
            owner: "java/lang/reflect/Array".into(),
            name: "set".into(),
            descriptor: "(Ljava/lang/Object;ILjava/lang/Object;)V".into(),
        };
        assert_eq!(
            runtime
                .invoke_reflect_array(
                    &set,
                    &[
                        array.clone(),
                        Value::Int(1),
                        Value::Ref(Some("beta".into()))
                    ],
                    "demo/Reflective",
                    "probe",
                )
                .unwrap(),
            Some(Value::Void)
        );
        let length = MethodRef {
            owner: "java/lang/reflect/Array".into(),
            name: "getLength".into(),
            descriptor: "(Ljava/lang/Object;)I".into(),
        };
        assert_eq!(
            runtime
                .invoke_reflect_array(
                    &length,
                    std::slice::from_ref(&array),
                    "demo/Reflective",
                    "probe",
                )
                .unwrap(),
            Some(Value::Int(2))
        );
        let get = MethodRef {
            owner: "java/lang/reflect/Array".into(),
            name: "get".into(),
            descriptor: "(Ljava/lang/Object;I)Ljava/lang/Object;".into(),
        };
        assert_eq!(
            runtime
                .invoke_reflect_array(
                    &get,
                    &[array.clone(), Value::Int(1)],
                    "demo/Reflective",
                    "probe",
                )
                .unwrap(),
            Some(Value::Ref(Some("beta".into())))
        );
        let set_boolean = MethodRef {
            owner: "java/lang/reflect/Array".into(),
            name: "setBoolean".into(),
            descriptor: "(Ljava/lang/Object;IZ)V".into(),
        };
        assert_eq!(
            runtime
                .invoke_reflect_array(
                    &set_boolean,
                    &[array.clone(), Value::Int(0), Value::Int(1),],
                    "demo/Reflective",
                    "probe",
                )
                .unwrap(),
            Some(Value::Void)
        );
        let get_boolean = MethodRef {
            owner: "java/lang/reflect/Array".into(),
            name: "getBoolean".into(),
            descriptor: "(Ljava/lang/Object;I)Z".into(),
        };
        assert_eq!(
            runtime
                .invoke_reflect_array(
                    &get_boolean,
                    &[array, Value::Int(0)],
                    "demo/Reflective",
                    "probe",
                )
                .unwrap(),
            Some(Value::Int(1))
        );
        let long_array = runtime
            .invoke_reflect_array(
                &new_instance,
                &[Value::Ref(Some("long".into())), Value::Int(1)],
                "demo/Reflective",
                "probe",
            )
            .unwrap()
            .unwrap();
        let set_long = MethodRef {
            owner: "java/lang/reflect/Array".into(),
            name: "setLong".into(),
            descriptor: "(Ljava/lang/Object;IJ)V".into(),
        };
        runtime
            .invoke_reflect_array(
                &set_long,
                &[long_array.clone(), Value::Int(0), Value::Int(42)],
                "demo/Reflective",
                "probe",
            )
            .unwrap();
        let get_long = MethodRef {
            owner: "java/lang/reflect/Array".into(),
            name: "getLong".into(),
            descriptor: "(Ljava/lang/Object;I)J".into(),
        };
        assert_eq!(
            runtime
                .invoke_reflect_array(
                    &get_long,
                    &[long_array, Value::Int(0)],
                    "demo/Reflective",
                    "probe",
                )
                .unwrap(),
            Some(Value::Int(42))
        );
    }

