    #[test]
    fn callback_info_returnable_round_trips_and_is_bounded() {
        let mut infos = CallbackInfos::new();
        let marker = "mixin/callback-info/demo/Target#number";
        let text = "mixin/callback-info/demo/Target#text";
        let unknown = "mixin/callback-info/demo/Target#unknown";
        assert!(infos.set_return(unknown, Value::Int(1)).is_err());
        assert!(infos.set_actual(unknown, Value::Int(1)).is_err());
        assert!(infos.current(unknown).is_err());
        assert!(infos.take_override(unknown, "I").is_err());

        infos.open(marker).unwrap();
        infos.set_actual(marker, Value::Int(5)).unwrap();
        assert_eq!(infos.current(marker).unwrap(), Value::Int(5));
        assert_eq!(infos.take_override(marker, "I").unwrap(), None);

        // javac boxes the primitive, so `setReturnValue` sees a reference that
        // is unboxed against the target's declared descriptor.
        infos
            .set_return(marker, Value::Boxed(Boxed::Integer(7)))
            .unwrap();
        assert_eq!(
            infos.current(marker).unwrap(),
            Value::Boxed(Boxed::Integer(7)),
            "getReturnValue reads the override once one exists"
        );
        assert_eq!(
            infos.take_override(marker, "I").unwrap(),
            Some(Value::Int(7))
        );
        // `Void` clears the override and `getReturnValue` falls back to the
        // target's own result.
        infos.set_return(marker, Value::Void).unwrap();
        assert_eq!(infos.current(marker).unwrap(), Value::Int(5));
        assert_eq!(infos.take_override(marker, "I").unwrap(), None);

        infos.open(text).unwrap();
        infos
            .set_actual(text, Value::Ref(Some("actual".into())))
            .unwrap();
        infos
            .set_return(text, Value::Ref(Some("override".into())))
            .unwrap();
        assert_eq!(
            infos.take_override(text, "Ljava/lang/String;").unwrap(),
            Some(Value::Ref(Some("override".into())))
        );

        // A reference cannot satisfy a primitive target, and a primitive
        // cannot satisfy a reference target.
        infos
            .set_return(marker, Value::Ref(Some("not-a-number".into())))
            .unwrap();
        assert!(infos.take_override(marker, "I").is_err());
        infos
            .open("mixin/callback-info/demo/Target#primitive")
            .unwrap();
        infos
            .set_return("mixin/callback-info/demo/Target#primitive", Value::Int(1))
            .unwrap();
        assert!(
            infos
                .take_override(
                    "mixin/callback-info/demo/Target#primitive",
                    "Ljava/lang/String;"
                )
                .is_err()
        );
    }

    #[test]
    fn executes_bounded_single_hook_mixin_overwrite_replacement() {
        let target = ClassFile {
            name: "demo/Target".into(),
            super_name: "java/lang/Object".into(),
            pool: vec![Cp::Empty],
            bootstrap_methods: Vec::new(),
            fields: Vec::new(),
            methods: vec![Method {
                name: "tick".into(),
                descriptor: "()I".into(),
                access: 9,
                code: Some(vec![0x08, 0xac]), // iconst_5; ireturn
                max_locals: 0,
                max_stack: 0,

                annotations: Vec::new(),
            }],

            annotations: Vec::new(),
            raw: Vec::new(),
        };
        let replacement = ClassFile {
            name: "demo/Mixin".into(),
            super_name: "java/lang/Object".into(),
            pool: vec![Cp::Empty],
            bootstrap_methods: Vec::new(),
            fields: Vec::new(),
            methods: vec![Method {
                name: "tick".into(),
                descriptor: "()I".into(),
                access: 9,
                code: Some(vec![0x10, 9, 0xac]), // bipush 9; ireturn
                max_locals: 0,
                max_stack: 0,

                annotations: Vec::new(),
            }],

            annotations: Vec::new(),
            raw: Vec::new(),
        };
        let jar = NativeJar::from_classes([target, replacement]);
        let mut plan = MixinInjectionPlan::inject_at_head(
            MethodRef {
                owner: "demo/Target".into(),
                name: "tick".into(),
                descriptor: "()I".into(),
            },
            MethodRef {
                owner: "demo/Mixin".into(),
                name: "tick".into(),
                descriptor: "()I".into(),
            },
        );
        plan.at.clear();
        let report = jar
            .execute_mixin_overwrite(&plan, None, &[], &mut NullHost)
            .unwrap();
        assert_eq!(report.callback_result, Value::Int(9));
        assert_eq!(report.target_result, Value::Int(9));
        plan.at = "HEAD".into();
        let error = jar
            .execute_mixin_overwrite(&plan, None, &[], &mut NullHost)
            .unwrap_err();
        assert!(error.to_string().contains("empty @At"));
    }

    #[test]
    fn standard_host_maps_fabric_entrypoint_containers() {
        let mut host = StdHost::new()
            .with_mod("demo", "1.2.3")
            .with_fabric_entrypoint("main", "demo.Main", "demo")
            .with_fabric_entrypoint("client", "demo.Client", "demo");
        let loader = Value::Ref(Some("fabric-loader".into()));
        let entries = MethodRef {
            owner: "net/fabricmc/loader/api/FabricLoader".into(),
            name: "getEntrypoints".into(),
            descriptor: "(Ljava/lang/String;)Ljava/util/List;".into(),
        };
        let main = host
            .invoke_instance(&entries, &loader, &[Value::Ref(Some("main".into()))])
            .unwrap();
        assert_eq!(
            host.invoke_instance(
                &MethodRef {
                    owner: "java/util/List".into(),
                    name: "size".into(),
                    descriptor: "()I".into(),
                },
                &main,
                &[],
            )
            .unwrap(),
            Value::Int(1)
        );
        let typed_entries = host
            .invoke_instance(
                &MethodRef {
                    owner: "net/fabricmc/loader/api/FabricLoader".into(),
                    name: "getEntrypointContainers".into(),
                    descriptor: "(Ljava/lang/String;Ljava/lang/Class;)Ljava/util/List;".into(),
                },
                &loader,
                &[
                    Value::Ref(Some("main".into())),
                    Value::Ref(Some("class/net.fabricmc.api.ModInitializer".into())),
                ],
            )
            .unwrap();
        assert_eq!(
            host.invoke_instance(
                &MethodRef {
                    owner: "java/util/List".into(),
                    name: "size".into(),
                    descriptor: "()I".into(),
                },
                &typed_entries,
                &[],
            )
            .unwrap(),
            Value::Int(1),
            "the generic Fabric entrypoint-container overload must retain the same ordered rows"
        );
        let container = host
            .invoke_instance(
                &MethodRef {
                    owner: "java/util/List".into(),
                    name: "get".into(),
                    descriptor: "(I)Ljava/lang/Object;".into(),
                },
                &main,
                &[Value::Int(0)],
            )
            .unwrap();
        assert_eq!(
            host.invoke_instance(
                &MethodRef {
                    owner: "net/fabricmc/loader/api/EntrypointContainer".into(),
                    name: "getEntrypointClass".into(),
                    descriptor: "()Ljava/lang/Class;".into(),
                },
                &container,
                &[],
            )
            .unwrap(),
            Value::Ref(Some("demo.Main".into()))
        );
        assert_eq!(
            host.invoke_instance(
                &MethodRef {
                    owner: "net/fabricmc/loader/api/EntrypointContainer".into(),
                    name: "getProvider".into(),
                    descriptor: "()Lnet/fabricmc/loader/api/ModContainer;".into(),
                },
                &container,
                &[],
            )
            .unwrap(),
            Value::Ref(Some("mod-container/demo/1.2.3".into()))
        );
        let client = host
            .invoke_instance(&entries, &loader, &[Value::Ref(Some("client".into()))])
            .unwrap();
        assert_eq!(
            host.invoke_instance(
                &MethodRef {
                    owner: "java/util/List".into(),
                    name: "size".into(),
                    descriptor: "()I".into(),
                },
                &client,
                &[],
            )
            .unwrap(),
            Value::Int(1)
        );
        assert!(host.fabric_entrypoint_containers().iter().any(|entry| {
            entry.kind == "client" && entry.class == "demo.Client" && entry.provider == "demo"
        }));
    }

