    fn string_array(values: &[&str]) -> AnnotationValue {
        AnnotationValue::Array(
            values
                .iter()
                .map(|value| AnnotationValue::String((*value).into()))
                .collect(),
        )
    }

    fn inject_annotation(method: &str, anchor: &str, cancellable: bool) -> Annotation {
        Annotation {
            descriptor: "Lorg/spongepowered/asm/mixin/injection/Inject;".into(),
            values: BTreeMap::from([
                ("method".into(), string_array(&[method])),
                (
                    "at".into(),
                    AnnotationValue::Array(vec![AnnotationValue::Annotation(Box::new(
                        Annotation {
                            descriptor: "Lorg/spongepowered/asm/mixin/injection/At;".into(),
                            values: BTreeMap::from([(
                                "value".into(),
                                AnnotationValue::String(anchor.into()),
                            )]),
                        },
                    ))]),
                ),
                ("cancellable".into(), AnnotationValue::Bool(cancellable)),
            ]),
        }
    }

    fn marker_pool(probe_method: &str) -> Vec<Cp> {
        vec![
            Cp::Empty,
            Cp::Utf8("demo/Probe".into()),
            Cp::Class(1),
            Cp::Utf8(probe_method.into()),
            Cp::Utf8("()V".into()),
            Cp::NameType {
                name: 3,
                descriptor: 4,
            },
            Cp::MethodRef { class: 2, nt: 5 },
        ]
    }

    fn test_method(
        name: &str,
        descriptor: &str,
        code: Vec<u8>,
        annotations: Vec<Annotation>,
    ) -> Method {
        Method {
            name: name.into(),
            descriptor: descriptor.into(),
            access: 9,
            code: Some(code),
            max_locals: 2,
            max_stack: 0,
            annotations,
        }
    }

    fn target_class() -> ClassFile {
        let body = vec![0xb8, 0x00, 0x06, 0xb1]; // invokestatic demo/Probe.target; return
        ClassFile {
            name: "demo/Target".into(),
            super_name: "java/lang/Object".into(),
            pool: marker_pool("target"),
            bootstrap_methods: Vec::new(),
            fields: Vec::new(),
            methods: vec![
                test_method("run", "()V", body.clone(), Vec::new()),
                test_method("run", "(I)V", body, Vec::new()),
            ],
            annotations: Vec::new(),
            raw: Vec::new(),
        }
    }

    /// A mixin whose callback calls `demo/Probe.<probe>()V`, which the test
    /// host records, so execution order is observable without javac.
    fn marker_mixin(
        class: &str,
        inject_method: &str,
        anchor: &str,
        cancellable: bool,
        callback: &str,
        probe: &str,
    ) -> ClassFile {
        ClassFile {
            name: class.into(),
            super_name: "java/lang/Object".into(),
            pool: marker_pool(probe),
            bootstrap_methods: Vec::new(),
            fields: Vec::new(),
            methods: vec![test_method(
                callback,
                "()V",
                vec![0xb8, 0x00, 0x06, 0xb1],
                vec![inject_annotation(inject_method, anchor, cancellable)],
            )],
            annotations: vec![Annotation {
                descriptor: "Lorg/spongepowered/asm/mixin/Mixin;".into(),
                values: BTreeMap::from([("targets".into(), string_array(&["Ldemo/Target;"]))]),
            }],
            raw: Vec::new(),
        }
    }

    #[derive(Default)]
    struct MarkerHost {
        markers: Vec<String>,
    }

    impl Host for MarkerHost {
        fn invoke(&mut self, r: &MethodRef, _: &[Value]) -> Result<Value, NativeError> {
            self.markers.push(format!("{}#{}", r.owner, r.name));
            Ok(Value::default_for(return_desc(&r.descriptor)))
        }
    }

    #[test]
    fn discovered_mixins_run_in_plan_order_and_report_every_callback() {
        let jar = NativeJar::from_classes([
            target_class(),
            marker_mixin("demo/AMixin", "run()V", "HEAD", false, "alpha", "alpha"),
            marker_mixin("demo/BMixin", "run()V", "HEAD", false, "beta", "beta"),
        ]);
        // Both mixins name the same overload, so discovery deduplicates it.
        assert_eq!(
            jar.discovered_mixin_targets(),
            vec![MethodRef {
                owner: "demo/Target".into(),
                name: "run".into(),
                descriptor: "()V".into(),
            }]
        );

        let mut host = MarkerHost::default();
        let report = jar
            .execute_discovered_mixins(
                &MethodRef {
                    owner: "demo/Target".into(),
                    name: "run".into(),
                    descriptor: "()V".into(),
                },
                None,
                &[],
                &mut host,
            )
            .unwrap();
        assert_eq!(report.callback_results, vec![Value::Void, Value::Void]);
        assert_eq!(report.callback_result, Value::Void);
        assert_eq!(report.target_result, Value::Void);
        assert_eq!(
            host.markers,
            vec!["demo/Probe#alpha", "demo/Probe#beta", "demo/Probe#target"],
            "HEAD callbacks run in plan order before the target, once"
        );
    }

    /// A jar whose `fabric.mod.json` declares one Mixin config holding `config`.
    fn configured_jar(classes: impl IntoIterator<Item = ClassFile>, config: &str) -> NativeJar {
        let mut jar = NativeJar::from_classes(classes);
        jar.resource_bytes.insert(
            "fabric.mod.json".into(),
            br#"{"id":"demo","version":"1","mixins":["demo.mixins.json"]}"#.to_vec(),
        );
        jar.resource_bytes
            .insert("demo.mixins.json".into(), config.as_bytes().to_vec());
        jar
    }

    #[test]
    fn discovered_mixins_skip_classes_no_config_lists() {
        let jar = configured_jar(
            [
                target_class(),
                marker_mixin(
                    "demo/ListedMixin",
                    "run()V",
                    "HEAD",
                    false,
                    "listed",
                    "listed",
                ),
                marker_mixin(
                    "demo/UnlistedMixin",
                    "run()V",
                    "HEAD",
                    false,
                    "unlisted",
                    "unlisted",
                ),
            ],
            r#"{"mixins":["demo.ListedMixin"]}"#,
        );
        let target = MethodRef {
            owner: "demo/Target".into(),
            name: "run".into(),
            descriptor: "()V".into(),
        };

        // The side-agnostic entry only asks whether a config claims the class.
        let mut host = MarkerHost::default();
        let report = jar
            .execute_discovered_mixins(&target, None, &[], &mut host)
            .unwrap();
        assert_eq!(
            host.markers,
            vec!["demo/Probe#listed", "demo/Probe#target"],
            "a plan no config lists never runs"
        );
        assert_eq!(report.skipped_plans.len(), 1);
        assert_eq!(report.skipped_plans[0].callback.owner, "demo/UnlistedMixin");
        assert_eq!(report.skipped_plans[0].reason, MixinSkipReason::NotInConfig);

        // A selected side gates through the same rule and reports it too.
        let mut host = MarkerHost::default();
        let report = jar
            .execute_discovered_mixins_on(MixinSide::Server, &target, None, &[], &mut host)
            .unwrap();
        assert_eq!(host.markers, vec!["demo/Probe#listed", "demo/Probe#target"]);
        assert_eq!(
            report
                .skipped_plans
                .iter()
                .map(|row| row.reason.label())
                .collect::<Vec<_>>(),
            ["not-in-config"]
        );

        // A jar with no readable config: the side-agnostic entry stays
        // executable for fixtures and probes, while the side-aware entry
        // refuses every plan exactly as the load-time weave does.
        let plain = NativeJar::from_classes([
            target_class(),
            marker_mixin("demo/PlainMixin", "run()V", "HEAD", false, "plain", "plain"),
        ]);
        let mut host = MarkerHost::default();
        let report = plain
            .execute_discovered_mixins(&target, None, &[], &mut host)
            .unwrap();
        assert_eq!(host.markers, vec!["demo/Probe#plain", "demo/Probe#target"]);
        assert!(report.skipped_plans.is_empty());

        let mut host = MarkerHost::default();
        let report = plain
            .execute_discovered_mixins_on(MixinSide::Server, &target, None, &[], &mut host)
            .unwrap();
        assert_eq!(host.markers, vec!["demo/Probe#target"]);
        assert_eq!(report.skipped_plans[0].reason, MixinSkipReason::NotInConfig);
    }

