    /// Run the discovered plan for one `demo/Target` method that takes no
    /// arguments, so each rejection case stays one call.
    fn run_discovered(
        jar: &NativeJar,
        name: &str,
        host: &mut MarkerHost,
    ) -> Result<MixinExecutionReport, NativeError> {
        jar.execute_discovered_mixins(
            &MethodRef {
                owner: "demo/Target".into(),
                name: name.into(),
                descriptor: "()V".into(),
            },
            None,
            &[],
            host,
        )
    }

    #[test]
    fn callback_info_cancel_requires_an_owned_marker() {
        let mut infos = CallbackInfos::new();
        let marker = "mixin/callback-info/demo/Target#run";
        let error = infos.cancel(marker).unwrap_err();
        assert!(
            matches!(&error, NativeError::Metadata(message)
                if message.contains("is not owned by this execution") && message.len() < 200),
            "unexpected error: {error}"
        );
        assert!(
            infos.flag(marker).is_err(),
            "isCancelled needs the object too"
        );

        infos.open(marker).unwrap();
        assert!(!infos.flag(marker).unwrap());
        infos.cancel(marker).unwrap();
        assert!(infos.flag(marker).unwrap(), "cancel() round-trips");
        // Opening the object again keeps the flag an earlier callback set.
        infos.open(marker).unwrap();
        assert!(infos.flag(marker).unwrap());

        // The table is bounded: one object per injection point, and a jar past
        // the bound gets a diagnostic instead of growing the runtime.
        let mut bounded = CallbackInfos::new();
        for index in 0..MAX_CALLBACK_INFOS {
            bounded
                .open(&format!("mixin/callback-info/demo/Target#{index}"))
                .unwrap();
        }
        assert!(
            bounded
                .open("mixin/callback-info/demo/Target#overflow")
                .is_err()
        );
    }

    /// A static callback that calls `CallbackInfo.cancel()`, injected at HEAD.
    fn cancel_head_mixin() -> ClassFile {
        ClassFile {
            name: "demo/ZCancelMixin".into(),
            super_name: "java/lang/Object".into(),
            pool: vec![
                Cp::Empty,
                Cp::Utf8(CALLBACK_INFO_CLASS.into()),
                Cp::Class(1),
                Cp::Utf8("cancel".into()),
                Cp::Utf8("()V".into()),
                Cp::NameType {
                    name: 3,
                    descriptor: 4,
                },
                Cp::MethodRef { class: 2, nt: 5 },
            ],
            bootstrap_methods: Vec::new(),
            fields: Vec::new(),
            methods: vec![test_method(
                "onRun",
                &format!("({CALLBACK_INFO_DESC})V"),
                // aload_0; invokevirtual CallbackInfo.cancel; return
                vec![0x2a, 0xb6, 0x00, 0x06, 0xb1],
                vec![inject_annotation("run()V", "HEAD", true)],
            )],
            annotations: vec![Annotation {
                descriptor: "Lorg/spongepowered/asm/mixin/Mixin;".into(),
                values: BTreeMap::from([("targets".into(), string_array(&["Ldemo/Target;"]))]),
            }],
            raw: Vec::new(),
        }
    }

    #[test]
    fn discovered_mixins_run_head_then_target_then_return() {
        let jar = NativeJar::from_classes([
            target_class(),
            marker_mixin(
                "demo/HeadMixin",
                "run()V",
                "HEAD",
                false,
                "before",
                "before",
            ),
            marker_mixin(
                "demo/ReturnMixin",
                "run()V",
                "RETURN",
                false,
                "after",
                "after",
            ),
        ]);
        let mut host = MarkerHost::default();
        let report = run_discovered(&jar, "run", &mut host).unwrap();
        assert!(!report.cancelled);
        assert!(!report.return_value_overridden);
        assert_eq!(report.target_result, Value::Void);
        assert_eq!(report.callback_results, vec![Value::Void, Value::Void]);
        assert_eq!(
            host.markers,
            vec!["demo/Probe#before", "demo/Probe#target", "demo/Probe#after"],
            "HEAD runs before the single target body, RETURN after it"
        );
    }

    #[test]
    fn a_cancelled_head_callback_skips_the_target_and_return_callbacks() {
        let jar = NativeJar::from_classes([
            target_class(),
            marker_mixin(
                "demo/HeadMixin",
                "run()V",
                "HEAD",
                false,
                "before",
                "before",
            ),
            cancel_head_mixin(),
            marker_mixin(
                "demo/ReturnMixin",
                "run()V",
                "RETURN",
                false,
                "after",
                "after",
            ),
        ]);
        let mut host = MarkerHost::default();
        let report = run_discovered(&jar, "run", &mut host).unwrap();
        assert!(report.cancelled);
        assert!(!report.return_value_overridden);
        assert_eq!(
            report.target_result,
            Value::Void,
            "a cancelled void target answers its descriptor default"
        );
        assert_eq!(
            report.callback_results,
            vec![Value::Void, Value::Void],
            "the non-cancelling HEAD callback and the cancelling one both ran"
        );
        assert_eq!(
            host.markers,
            vec!["demo/Probe#before"],
            "the target body and the RETURN callback never run"
        );
    }

